import NodeSqlParser from 'node-sql-parser';
const { Parser } = NodeSqlParser;
import type { SQLParserDialect } from '@memberjunction/sql-dialect';
import type { SQLCTEExtraction } from '../sql-parser.js';
import { ExtractCTEsByParenScan, SkipLeadingCommentsAndWhitespace } from './cteParenScan.js';
import { FixMaxTypeSerialization, NodeSqlAstifyChecked } from './nodeSqlParserCore.js';

/**
 * The CTE split the structural IR (`ParseToIR`) has always used, kept exactly as it was so the
 * IR cannot drift: node-sql-parser first, with each body regenerated by its serializer as
 * `name AS (\n<body>\n)`, then a parenthesis scan. New code should read
 * `SqlDocument.CTEs()` or `SplitLeadingCTEs`, which return the text as written.
 */
export function FrozenExtractCTEs(sql: string, dialect: SQLParserDialect): SQLCTEExtraction | null {
    const stripped = SkipLeadingCommentsAndWhitespace(sql);
    if (!/^WITH\s/i.test(stripped)) return null;
    return extractCTEsViaAST(stripped, dialect.ParserDialect) ?? ExtractCTEsByParenScan(stripped);
}

function extractCTEsViaAST(sql: string, dialect: string): SQLCTEExtraction | null {
    try {
        const parser = new Parser();
        const ast = NodeSqlAstifyChecked(sql, dialect);
        const singleAst = (Array.isArray(ast) ? ast[0] : ast) as unknown as Record<string, unknown>;
        if (!singleAst.with || !Array.isArray(singleAst.with) || singleAst.with.length === 0) return null;

        const cteDefinitions: string[] = [];
        for (const cte of singleAst.with as unknown[]) {
            const cteRecord = cte as { name: { value: string }; stmt: { ast: unknown } };
            const bodySQL = FixMaxTypeSerialization(parser.sqlify(cteRecord.stmt.ast as NodeSqlParser.AST, { database: dialect }));
            cteDefinitions.push(`${cteRecord.name.value} AS (\n${bodySQL}\n)`);
        }

        const mainAst = { ...singleAst, with: null } as unknown as NodeSqlParser.AST;
        const mainStatement = FixMaxTypeSerialization(parser.sqlify(mainAst, { database: dialect }));
        return { CTEDefinitions: cteDefinitions, MainStatement: mainStatement, UsedASTParsing: true };
    } catch {
        return null;
    }
}
